# T11b oracle: drives the real CircuitPython Orion app loop (Orion.run) under CPython
# with faked hardware, one scripted input per pass, and records the UI/engine state
# after each pass. The expected values in tests/native/fixtures/t11b_traces.inc are
# generated by this script; they never come from the C++ code under test.
#
# Usage: python -I t11b_harness.py <repo_root> [--json]
#
# Each pass holds at most one input event (key edge, encoder edge or encoder turn)
# so the sequential C++ controller and the batched Python loop see the same order.
# The UI queue is flushed after each pass (the Python loop drains one callback per
# pass; the C++ model flushes its queue when it is built).
import sys, os, types, json, importlib

REPO = sys.argv[1]
SRC = os.path.join(REPO, "circuitpython-source", "src")
sys.path.insert(0, SRC)

# ---------------------------------------------------------------- fakes
MAX = 1 << 29
HALF = MAX // 2
clock = {"ms": 1000}

ticks = types.ModuleType("adafruit_ticks")
ticks.ticks_ms = lambda: clock["ms"] % MAX
ticks.ticks_add = lambda t, d: (t + d) % MAX
ticks.ticks_diff = lambda a, b: ((a - b + HALF) % MAX) - HALF
ticks.ticks_less = lambda a, b: ticks.ticks_diff(a, b) < 0
sys.modules["adafruit_ticks"] = ticks


class Anything:
    def __init__(self, *a, **k):
        pass

    def __getattr__(self, name):
        return Anything()

    def __call__(self, *a, **k):
        return Anything()

    def __setattr__(self, name, value):
        object.__setattr__(self, name, value)


for name in ("keypad", "microcontroller", "usb_midi", "board", "digitalio", "neopixel",
             "rotaryio", "adafruit_debouncer", "supervisor"):
    sys.modules[name] = Anything()
