def midi_class(modname, clsname):
    m = types.ModuleType("adafruit_midi." + modname)
    cls = type(clsname, (), {"__init__": lambda self, *a, **k: setattr(self, "args", a)})
    setattr(m, clsname, cls)
    sys.modules["adafruit_midi." + modname] = m
    return cls


