rainbow = types.ModuleType("rainbowio")


def colorwheel(pos):
    pos = pos % 256
    if pos < 85:
        return ((255 - pos * 3) << 16) | ((pos * 3) << 8)
    if pos < 170:
        pos -= 85
        return ((255 - pos * 3) << 8) | (pos * 3)
    pos -= 170
    return ((pos * 3) << 16) | (255 - pos * 3)


rainbow.colorwheel = colorwheel
sys.modules["rainbowio"] = rainbow


class TileGrid:
    def __init__(self, bitmap=None, pixel_shader=None, width=1, height=1, tile_width=1,
                 tile_height=1, x=0, y=0, **k):
        self.width = width
        self.height = height
        self.x = x
        self.y = y
        self.tiles = [0] * (width * height)

    def __getitem__(self, i):
        return self.tiles[i]

    def __setitem__(self, i, v):
        self.tiles[i] = v


