        self.display = Anything()
        self.encoder_switch_debounced = Anything()
        self._keys = Anything()
        self._key_pins = None
        self.encoder = 0
        self.midi = FakeMidi()
        self.pixels = FakePixels()
        self.keys = FakeKeys()
        self.NoteOn = lambda *a: ("NoteOn", a)
        self.NoteOff = lambda *a: ("NoteOff", a)


