# ---------------------------------------------------------------- recorder
counters = {"all_notes_off": 0}
_orig_off = O.OutputManager.all_notes_off


def counting_off(self, channel=None):
    counters["all_notes_off"] += 1
    return _orig_off(self, channel)


O.OutputManager.all_notes_off = counting_off


class StopLoop(Exception):
    pass


def snapshot(orion):
    orion.flush_ui_queue()
    st = orion.state
    mod = st.chain_modules[st.active_chain]
    parms = mod.get_parms() if mod is not None else []
    vals = []
    for p in parms:
        v = p.value
        vals.append(float(v) if v is not None else 0.0)
    ps = orion.ui_manager.parameter_section
    return {
        "section": st.active_ui_section,
        "chain": st.active_chain,
        "parm": st.active_parm,
        "scroll": ps.scroll_offset,
        "nav": st.nav_keys_state,
        "swap": orion.chain_swap_mode,
        "mode": st.active_chain_mode,
        "octave": st.octave,
        "offset": st.key_offset,
        "running": int(orion.transport.running),
        "tmode": st.transport_mode,
        "selector": st.module_selector_active_module,
        "key": st.key,
        "scale": st.scale,
        "count": len(parms),
        "notes_off": counters["all_notes_off"],
        "slots": ",".join(m.name if m is not None else "none" for m in st.chain_modules),
        "values": vals,
    }


# step encoding: ("k", key, down) ("e", down) ("t", delta) ("w", ms) ("n",) = idle pass
def run_scenario(steps, setup=None):
    clock["ms"] = 1000
    counters["all_notes_off"] = 0
    orion = Orion()
    if setup:
        setup(orion)
    inp = orion.input_manager
    script = list(steps)
    snaps = []
    downstate = bytearray(13)
    state = {"i": 0}

    def get_inputs():
        snaps.append(snapshot(orion))
        if state["i"] >= len(script):
            raise StopLoop()
        step = script[state["i"]]
        state["i"] += 1
        pressed = bytearray(13)
        released = bytearray(13)
        delta = 0
        kind = step[0]
        if kind == "k":
            idx = step[1] + 1
            if step[2]:
                pressed[idx] = 1
                downstate[idx] = 1
            else:
                released[idx] = 1
                downstate[idx] = 0
        elif kind == "e":
            if step[1]:
                pressed[0] = 1
                downstate[0] = 1
            else:
                released[0] = 1
                downstate[0] = 0
        elif kind == "t":
            delta = step[1]
        elif kind == "w":
            clock["ms"] += step[1]
        return pressed, released, delta, downstate

    inp.get_inputs = get_inputs
    try:
        orion.run()
    except StopLoop:
        pass
    run_scenario.last_scene_text = save_scene_text(orion)
    return snaps[1:]  # drop the pre-input snapshot


def save_scene_text(orion):
    """Scene text exactly as core/scenes.py save_scene writes it for the final state."""
    import tempfile
    from apps.Orion.core import scenes
    with tempfile.TemporaryDirectory() as tmp:
        scenes.save_scene(orion.state, 0, base_dir=tmp)
        with open(os.path.join(tmp, "Scene01"), "r", newline="") as f:
            return f.read()


def K(k):
    return [("k", k, 1), ("k", k, 0)]


def combo(*keys):
    out = [("e", 1)]
    for k in keys:
        out += K(k)
    out.append(("e", 0))
    return out


SCENARIOS = {}


def click():
    return [("e", 1), ("e", 0)]


def hold(*keys):
    out = [("e", 1)]
    for k in keys:
        out += K(k)
    out.append(("e", 0))
    return out


# Physical key index = KEY number - 1.
KEY1, KEY2, KEY3, KEY4, KEY5, KEY6, KEY7, KEY8, KEY9, KEY10, KEY11, KEY12 = range(12)

# Notes mode: octave/offset keys, then navigation mode keys in every section.
SCENARIOS["nav_notes"] = (
    hold(KEY8, KEY8, KEY11, KEY10, KEY12, KEY5)
    + hold(KEY7, KEY8, KEY8, KEY11, KEY10, KEY12, KEY7, KEY12, KEY12, KEY10)
)
SCENARIOS["nav_parms"] = (
    hold(KEY7, KEY9, KEY11, KEY11, KEY11, KEY8, KEY10, KEY12, KEY9)   # chain->selection->edit
    + hold(KEY8, KEY11, KEY10, KEY12, KEY9, KEY4, KEY8, KEY11, KEY10, KEY12, KEY9)
    + hold(KEY5, KEY8, KEY11, KEY10, KEY12, KEY7)
)
SCENARIOS["encoder_flow"] = (
    [("t", 1), ("t", 1), ("t", -3), ("t", -1), ("t", 1)]            # chain moves wrap 10 slots
    + click()                                                      # SET: enter parameter selection
    + [("t", 1), ("t", 1), ("t", -1), ("t", -5), ("t", 9)]         # parameter selection wrap (-2..4)
    + [("t", 3)] + click() + [("t", 1), ("t", 1), ("t", -4)] + click()   # edit SCL, exit
    + [("t", -1), ("t", -1), ("t", -1)]
)
SCENARIOS["jumps"] = (
    hold(KEY3, KEY6, KEY5, KEY4, KEY3, KEY4, KEY9, KEY9, KEY3, KEY6, KEY9, KEY5)
)
# Module selection: slot 1 gets arp_walk (registry index 2) and slot 2 transpose (16).
_select_arp_walk = ([("t", 1)] + hold(KEY4) + [("t", 2)] + hold(KEY9))
_select_transpose = (hold(KEY5) + [("t", 1)] + hold(KEY4) + [("t", 16)] + hold(KEY9))
SCENARIOS["module_select"] = (
    [("t", 1)] + hold(KEY4) + [("t", 2), ("t", 1), ("t", 18), ("t", -1)]   # selector wraps over 18 entries
    + hold(KEY9)                                                          # apply
    + [("t", 1), ("t", 1)]
)
SCENARIOS["paging"] = (
    _select_arp_walk + [("t", 1)] * 18 + [("t", -1)] * 19 + [("t", 7), ("t", -3), ("t", 40)]
    + hold(KEY7) + hold(KEY11, KEY11, KEY8)
)
SCENARIOS["set_out_settings"] = (
    [("t", -1)] + click()                                       # SET parameter selection
    + click() + [("t", 3)] + click()                           # KEY edit
    + [("t", 1)] + click() + [("t", 2)] + click()              # SCL
    + [("t", 1)] + click() + [("t", -10), ("t", 400)] + click()   # BPM (clamped)
    + [("t", 1)] + click() + [("t", 4), ("t", 20)] + click()   # SWNG (percent, step .05)
    + [("t", 1)] + click() + [("t", 1)] + click()              # TRMDE (exit callback applies)
    + hold(KEY5)
    + [("t", -1)] * 0 + [("t", 8)] + click()                    # to OUT, selection
    + click() + [("t", 4), ("t", -9), ("t", 40)] + click()     # OUTCH
    + [("t", 1)] + click() + [("t", 1)] + click()              # PRNT
    + hold(KEY5) + [("t", 1)] + click()                         # SETTINGS selection
    + click() + [("t", 1), ("t", -1)] + click()                # SCENE edit and back: exit on the active scene is a no-op
    + [("t", 1)] + click()                                     # SAVSCN button (enter, returns)
    + [("t", 1)] + click() + [("t", 3), ("t", -3)] + click()    # CPYSCN edit and back to '>': exit copies nothing
    + [("t", 1)] + click() + click()                           # RSTSCN arm then exit (value 0)
    + [("t", 1)] + click()                                     # RAM button
    + [("t", 1)] + click() + [("t", -4), ("t", 30)] + click()  # KEYBRI
)
SCENARIOS["routing_rows"] = (
    _select_transpose + [("t", 1)] * 3 + click()                 # SEMI/OCT/INSCL, SRC
    + [("t", 4)] + click() + [("t", 2), ("t", 9)] + click()     # edit some rows
    + [("t", 1)] + click() + [("t", 3)] + click()
    + [("t", 1)] + click() + [("t", -3)] + click()
)
SCENARIOS["swap"] = (
    _select_arp_walk + _select_transpose + hold(KEY5) + [("t", -1)]
    + [("e", 1), ("w", 999), ("n",), ("e", 0)]                  # 999 ms: parameter selection, no swap
    + hold(KEY5)
    + [("e", 1), ("w", 1000), ("n",), ("e", 0)]                 # 1000 ms: pending -> active swap mode
    + [("t", 1), ("t", 1), ("t", -1), ("t", -5), ("t", 9)]      # swap, clamp at the ends
    + click()                                                   # leave swap mode
    + [("e", 1), ("w", 1000), ("k", KEY8, 1), ("k", KEY8, 0), ("e", 0)]   # key during pending cancels
    + [("e", 1), ("w", 1500), ("n",), ("e", 0), ("t", 1)]       # swap again, then turn
    + [("t", -2), ("e", 1), ("e", 0)]
)

def edit(rows_down, delta):
    """In parameter selection: move rows_down, enter edit, turn, exit."""
    out = []
    if rows_down:
        out.append(("t", rows_down))
    return out + click() + [("t", delta)] + click()


def select_module(registry_index):
    return hold(KEY4) + [("t", registry_index)] + hold(KEY9)


SCENARIOS["scene_default"] = [("n",)]
SCENARIOS["scene_rich"] = (
    hold(KEY8, KEY8, KEY12)                                   # octave +2, pad offset +1
    + select_module(3)                                        # matrix input
    + edit(0, 3) + edit(1, 2) + edit(1, 1) + edit(1, 1) + edit(1, 1) + edit(1, 2)   # pad 3, note, chord, 7th, 9th, inv
    + edit(1, 2) + edit(5, 3)                                 # sus ; bass? (rows down)
    + hold(KEY5) + [("t", 1)]
    + select_module(2)                                        # arp_walk in slot 1
    + edit(2, 3) + edit(1, 1) + edit(1, 6) + edit(7, 2) + edit(1, 3)
    + hold(KEY5) + [("t", 1)]
    + select_module(8)                                        # euclid in slot 2
    + edit(0, 2) + edit(2, 3) + edit(1, 5) + edit(1, -9)
    + hold(KEY5) + [("t", 1)]
    + select_module(16)                                       # transpose in slot 3
    + edit(0, 3) + edit(1, 1) + edit(1, 1) + edit(1, 2) + edit(1, 3) + edit(1, 4)
    + hold(KEY5) + [("t", -4)] + click()                      # SET parameter selection
    + edit(0, 5) + edit(1, 3) + edit(1, -7) + edit(1, 3)       # KEY, SCL, BPM, SWNG
    + hold(KEY5) + [("t", 8)] + click()                       # OUT parameter selection
    + edit(0, 4) + edit(1, 1)                                 # OUTCH, PRNT
    + hold(KEY5, KEY3, KEY5)
)



# ---------------------------------------------------------------- model tables
def emit_model_tables(path):
    """State.move_active_parm_elem, ParameterSection paging and Parm display formatting,
    computed by the real source classes."""
    from apps.Orion.core import ui as UI
    from apps.Orion.core import parms as P
    lines = ["// Generated by tools/arduino/oracle/t11b_harness.py --emit-model. Do not edit.", ""]

    # State.move_active_parm_elem
    st = S.State(FakeMacroPad())
    st.update_parm_count = lambda: None
    lines.append("struct MoveCase { int count; int is_static; int active; int delta; int expect; };")
    lines.append("static const MoveCase kMoveCases[] = {")
    for count in (0, 1, 2, 5, 13, 16):
        for static in (0, 1):
            for active in range(-2, max(count, 1)):
                for delta in (-5, -3, -1, 1, 2, 5, 40, -40):
                    st.parm_count = count
                    st.active_chain = S.ChainElements.OUT if static else S.ChainElements.IN
                    st.active_parm = active
                    st.move_active_parm_elem(delta)
                    lines.append("  {%d, %d, %d, %d, %d}," % (count, static, active, delta, st.active_parm))
    lines.append("};")
    lines.append("")

    # ParameterSection paging
    class StubParm:
        def __init__(self, i):
            self.label = "P%d" % i
            self.display_value = str(i)

    class StubModule:
        label_length = 6
        def __init__(self, n):
            self.n = n
            self.parms = [StubParm(i) for i in range(n)]
        def get_parms(self):
            return self.parms

    state = S.State(FakeMacroPad())
    ps = UI.ParameterSection(state, Group())
    lcg = 12345
    def rnd(n):
        nonlocal lcg
        lcg = (lcg * 1103515245 + 12345) & 0x7FFFFFFF
        return (lcg >> 8) % n
    counts = (3, 4, 5, 6, 9, 13, 16)
    count = 13
    ops = []
    for i in range(500):
        if rnd(12) == 0:
            count = counts[rnd(len(counts))]
        active = rnd(count + 3) - 2
        op = "R" if rnd(4) == 0 else "U"
        state.chain_modules = [StubModule(count)] * S.TOTALSLOTCOUNT if hasattr(S, "TOTALSLOTCOUNT") else [StubModule(count)] * 10
        state.active_chain = 1
        state.active_parm = active
        if op == "R":
            ps.rebuild_parm_section()
        else:
            ps.update_parm_selection()
        ops.append((op, active, count, ps.parm_count, ps.scroll_offset, ps.last_active_parm))
    lines.append("struct PagingCase { char op; int active; int count; int parm_count; int scroll; int last_active; };")
    lines.append("static const PagingCase kPagingCases[] = {")
    for o in ops:
        lines.append("  {'%s', %d, %d, %d, %d, %d}," % o)
    lines.append("};")
    lines.append("")

    # Parm.get_display_value (as str() in set_text)
    rows = []
    def add(kind, parm, value_i, value_f, option_count=0, float_text=0):
        rows.append((kind, value_i, value_f, option_count, float_text, str(parm.get_display_value())))
    for v in (-24, -1, 0, 7, 127, 300):
        add("Integer", P.Parm("n", "N", P.IntParmType, v), v, 0.0)
    for v in (100, 105, 0, 5000):
        add("Decimal", P.Parm("g", "G", P.FloatParmType, v), 0, float(v), 0, 0)
    for v in (100.0, 0.5, 0.15, 12.5, 0.05, 0.0, -0.25):
        add("Decimal", P.Parm("g", "G", P.FloatParmType, v), 0, v, 0, 1)
    for v in (0, 0.05, 0.15, 0.285, 0.125, 0.5, 0.75, 1, 1.0, 0.995):
        add("Percent", P.Parm("p", "P", P.PercentParmType, v), 0, float(v))
    for v in (0, 1):
        add("Boolean", P.Parm("b", "B", P.BooleanParmType, v), v, 0.0)
    opts = ("NEXT", "ADD", "OUT+N", "OUT+S", "SKIP")
    for v in range(5):
        add("Enum", P.Parm("e", "E", P.EnumParmType, v, options=opts), v, 0.0, 5)
    for v in range(13):
        add("Rate", P.Parm("r", "R", P.RateParmType, v), v, 0.0)
    for v in range(25):
        add("Pattern", P.Parm("t", "T", P.PatternParmType, v), v, 0.0)
    for v in range(12):
        add("Note", P.Parm("k", "K", P.NoteParmType, v), v, 0.0)
    add("Button", P.Parm("x", "X", P.ButtonParmType, 0), 0, 0.0)
    lines.append("struct FormatCase { RowKind kind; int ivalue; float fvalue; int option_count; int float_text; const char* expect; };")
    lines.append("static const FormatCase kFormatCases[] = {")
    for r in rows:
        lines.append('  {RowKind::%s, %d, %rf, %d, %d, "%s"},' % r)
    lines.append("};")
    with open(path, "w", newline=chr(10)) as f:
        f.write(chr(10).join(lines) + chr(10))

if __name__ == "__main__":
    emit = None
    if "--emit-model" in sys.argv:
        emit_model_tables(sys.argv[sys.argv.index("--emit-model") + 1])
        sys.exit(0)
    if "--emit" in sys.argv:
        emit = sys.argv[sys.argv.index("--emit") + 1]
    out = {}
    for name, steps in SCENARIOS.items():
        out[name] = {"steps": steps, "trace": run_scenario(steps, lambda o: setattr(o.state, "active_parm", 0)),
                     "scene": run_scenario.last_scene_text}
    if emit:
        lines = ["// Generated by tools/arduino/oracle/t11b_harness.py from circuitpython-source/src/apps/Orion.",
                 "// Do not edit. Expected values come from running the real Orion.run loop.", ""]
        idents = []
        for name, data in out.items():
            ident = "".join(p.capitalize() for p in name.split("_"))
            idents.append((name, ident))
            lines.append("static const TraceStep k%sSteps[] = {" % ident)
            for st in data["steps"]:
                kind = st[0]
                a = st[1] if len(st) > 1 else 0
                b = st[2] if len(st) > 2 else 0
                lines.append("  {'%s', %d, %d}," % (kind, a, b))
            lines.append("};")
            lines.append("static const TraceExpect k%sExpect[] = {" % ident)
            for t in data["trace"]:
                vals = ", ".join(repr(float(v)) for v in t["values"][:20]) or "0"
                lines.append("  {%d, %d, %d, %d, %d, %d, %d, %d, %d, %d, %d, %d, %d, %d, %d, %d, \"%s\", %d, {%s}}," % (
                    t["section"], t["chain"], t["parm"], t["scroll"], t["nav"], t["swap"], t["mode"], t["octave"],
                    t["offset"], t["running"], t["tmode"], t["selector"], t["key"], t["scale"], t["count"],
                    t["notes_off"], t["slots"], min(len(t["values"]), 20), vals))
            lines.append("};")
            lines.append("")
        lines.append("struct SceneText { const char* name; const char* text; };")
        lines.append("static const SceneText kSceneTexts[] = {")
        for name, data in out.items():
            if name.startswith("scene_"):
                body = data["scene"].replace(chr(13), "")
                esc = chr(92)
                text = body.replace(esc, esc + esc).replace(chr(34), esc + chr(34)).replace(chr(10), esc + "n" + chr(34) + chr(10) + "    " + chr(34))
                lines.append("  {" + chr(34) + name + chr(34) + ", " + chr(34) + text + chr(34) + "},")
        lines.append("};")
        lines.append("")
        lines.append("static const TraceScenario kScenarios[] = {")
        for name, ident in idents:
            lines.append('  {"%s", k%sSteps, k%sExpect, sizeof(k%sSteps) / sizeof(k%sSteps[0])},' % (name, ident, ident, ident, ident))
        lines.append("};")
        with open(emit, "w", newline="\n") as f:
            f.write("\n".join(lines) + "\n")
    elif "--json" in sys.argv:
        sys.stdout.write(json.dumps(out))
    else:
        for name, data in out.items():
            _real_print(name, len(data["steps"]), "passes")
